def signedHaarPacketReader (n : ℕ) (S : Finset (Fin (2 ^ n)))
    (θ : Fin (2 ^ n) → Bool) (y : Lp 𝕜 1 (volume.restrict (Set.Icc (0 : ℝ) 1))) : 𝕜 :=
  ∑ k ∈ S, signedValue (θ k) (scalarHaarPacketReader (𝕜 := 𝕜) n k y)

